using System.Collections.Generic;
using UnityEngine;

namespace Astrea.GameStates;

public class ChooseTargetStateAction : BattleActionCastStatesAction
{
	[Header("Targets")]
	[SerializeField]
	protected List<TargetEnum> targetUnits;

	[SerializeField]
	protected bool chooseSelf;

	public override void Execute(float d)
	{
	}

	protected void TargetSelected(TargetInstance target)
	{
		ActionFace actionFace = base.actionInstance.ActionFace;
		GameObject targetGameObject = target.gameObject;
		CorruptionStats componentInParent = target.GetComponentInParent<CorruptionStats>();
		if (componentInParent != null)
		{
			targetGameObject = componentInParent.gameObject;
			if (!actionFace.BattleAction.CheckCondition(targetGameObject, actionFace.ModifiedActionValue))
			{
				base.actionInstance.StopFollowingMouse();
				return;
			}
		}
		CastAction(delegate(GameObject source)
		{
			actionFace.BattleAction.CastTargetAmount(targetGameObject, actionFace.ModifiedActionValue, source);
		}, delegate(GameObject source)
		{
			actionFace.BattleAction.CastTarget(targetGameObject, source);
		}, targetGameObject);
		target.OnClick();
	}
}
